package io.knowledgebrain.space;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.space.groupprogresspolicy.v1.*;
/** Space-owned opt-in policy. Version is also a consent epoch; old grants never reactivate. */
final class GroupProgressPolicyStore {
 record Policy(UUID policyId,UUID groupId,UUID spaceId,long version,String mode,String audience,String updatedAt) {}
 record Member(UUID principalId,long membershipVersion) {}
 record Access(UUID principalId,UUID groupId,UUID spaceId,String role,long membershipVersion,long policyVersion,boolean enabled,String audience,List<Member> activeMembers) {}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Policy snapshot) {}
 record History(List<Revision> items,Long nextBefore) {}
 record Scope(UUID space,UUID owner) {}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 GroupProgressPolicyStore(DataSource source,Clock clock){sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException unavailable(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Group unavailable");}
 private Scope scope(UUID group){var rows=sql.query("SELECT s.space_id,s.owner_principal_id FROM group_space_origin g JOIN space s ON s.space_id=g.space_id WHERE g.group_id=? AND s.kind='GROUP' AND s.visibility='PRIVATE' AND s.state='ACTIVE' FOR UPDATE OF s",(rs,n)->new Scope(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class)),group);if(rows.isEmpty())throw unavailable();return rows.getFirst();}
 private Access access(UUID group,UUID actor,List<UUID> requested,Scope scope){
  var rows=sql.query("SELECT role,group_version FROM space_membership WHERE space_id=? AND principal_id=? AND state='ACTIVE'",(rs,n)->new Access(actor,group,scope.space(),rs.getString(1),rs.getLong(2),0,false,"OWNER",List.of()),scope.space(),actor);if(rows.isEmpty())throw unavailable();var who=rows.getFirst();if(!Set.of("OWNER","MEMBER","VIEWER").contains(who.role()))throw unavailable();if(!requested.isEmpty())owner(who,scope);
  var members=new ArrayList<Member>();if(!requested.isEmpty()){var args=new ArrayList<Object>();args.add(scope.space());args.addAll(requested);members.addAll(sql.query("SELECT principal_id,group_version FROM space_membership WHERE space_id=? AND state='ACTIVE' AND role IN ('OWNER','MEMBER','VIEWER') AND principal_id IN ("+String.join(",",Collections.nCopies(requested.size(),"?"))+") ORDER BY principal_id",(rs,n)->new Member(rs.getObject(1,UUID.class),rs.getLong(2)),args.toArray()));}
  var p=policy(group,scope.space());return new Access(actor,group,scope.space(),who.role(),who.membershipVersion(),p.version(),p.mode().equals("OWNER_SUMMARY"),"OWNER",List.copyOf(members));
 }
 private void owner(Access a,Scope scope){if(!a.role().equals("OWNER")||!scope.owner().equals(a.principalId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Group OWNER required");}
 Access check(UUID group,UUID actor,List<UUID> requested){if(requested==null||requested.size()>100||new HashSet<>(requested).size()!=requested.size())throw GroupBrowserRequest.bad();for(var id:requested)GroupBrowserRequest.id(id==null?null:id.toString());return tx.execute(s->{var scope=scope(group);return access(group,actor,requested,scope);});}
 private Policy policy(UUID group,UUID space){var rows=sql.query("SELECT snapshot::text FROM group_progress_policy WHERE group_id=? AND space_id=?",(rs,n)->json.readValue(rs.getString(1),Policy.class),group,space);return rows.isEmpty()?new Policy(null,group,space,0,"DISABLED","OWNER",null):rows.getFirst();}
 Policy get(UUID group,UUID actor){return tx.execute(s->{var scope=scope(group);access(group,actor,List.of(),scope);return policy(group,scope.space());});}
 Policy change(UUID group,UUID actor,long expected,String mode,String trace){if(expected<0||mode==null||!Set.of("DISABLED","OWNER_SUMMARY").contains(mode)||trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw GroupBrowserRequest.bad();return tx.execute(s->{var scope=scope(group);owner(access(group,actor,List.of(),scope),scope);var old=policy(group,scope.space());if(expected!=old.version())throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Sharing policy changed");if(old.mode().equals(mode))return old;
  String now=clock.instant().truncatedTo(ChronoUnit.MICROS).toString();var v=new Policy(old.policyId()==null?ids.next():old.policyId(),group,scope.space(),Math.addExact(old.version(),1),mode,"OWNER",now);
  if(old.version()==0)sql.update("INSERT INTO group_progress_policy VALUES (?,?,?,?,?,?::jsonb)",v.policyId(),group,v.spaceId(),v.version(),mode,json.writeValueAsString(v));else sql.update("UPDATE group_progress_policy SET version=?,mode=?,snapshot=?::jsonb WHERE policy_id=?",v.version(),mode,json.writeValueAsString(v),v.policyId());record(v,actor,trace);return v;
 });}
 History history(UUID group,UUID actor,long before,int limit){return tx.execute(s->{var scope=scope(group);owner(access(group,actor,List.of(),scope),scope);var p=policy(group,scope.space());if(p.policyId()==null)return new History(List.of(),null);var rows=sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM group_progress_policy_revision WHERE policy_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Policy.class)),p.policyId(),before,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new History(items,rows.size()>limit?items.getLast().version():null);});}
 private void record(Policy v,UUID actor,String trace){var at=Timestamp.from(Instant.parse(v.updatedAt()));sql.update("INSERT INTO group_progress_policy_revision VALUES (?,?,?,?,?,?::jsonb)",ids.next(),v.policyId(),v.version(),actor,at,json.writeValueAsString(v));var p=GroupProgressPolicySnapshotV1.newBuilder().setPolicyId(v.policyId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setVersion(v.version()).setMode(v.mode()).setAudience(v.audience()).setUpdatedAt(v.updatedAt()).build();var id=ids.next();var e=GroupProgressPolicyEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType("GroupProgressPolicyChanged").setEventVersion(1).setOccurredAtEpochMillis(at.toInstant().toEpochMilli()).setProducer("space-service").setAggregateType("GroupProgressPolicy").setAggregateId(v.policyId().toString()).setSpaceId(v.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(p.toByteString()).build();sql.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'group-progress-policy',?,'GroupProgressPolicyChanged',?,?,'space','group-progress-policy-events','1',?)",id,v.policyId(),at,trace,e.toByteArray());}
}
